{"filePath":"/root/work/gles-bridge-mod/build.gradle","content":"plugins {
    id 'fabric-loom' version '1.6-SNAPSHOT'
    id 'java'
}

group = 'net.glesbridge'
version = '1.0.0'
archivesBaseName = 'gles-bridge-mod'

repositories {
    mavenCentral()
    maven { url 'https://maven.fabricmc.net/' }
    maven { url 'https://maven.minecraftforge.net/' }
}

dependencies {
    minecraft 'com.mojang:minecraft:1.21'
    mappings loom.officialMojangMappings()

    modImplementation 'net.fabricmc:fabric-loader:0.16.14'
    modImplementation 'net.fabricmc.fabric-api:fabric-api:0.116.0+1.21'

    // LWJGL GLES bindings - we use the LWJGL that Minecraft bundles
    implementation 'org.lwjgl:lwjgl-gles:3.3.3'
    implementation 'org.lwjgl:lwjgl:3.3.3'
}

java {
    sourceCompatibility = JavaVersion.VERSION_21
    targetCompatibility = JavaVersion.VERSION_21
}

tasks.withType(JavaCompile).configureEach {
    options.encoding = 'UTF-8'
    options.compilerArgs << '-Xlint:unchecked' << '-Xlint:deprecation'
}

loom {
    mappingsChannel = 'official'
    mappingsVersion = '1.21'
}"}

